static const uint8_t k_phase4_header[12] = {
    0x46, 0x50, 0x4C, 0x59, 0x03, 0x01, 0x04, 0x00,
    0x00, 0x00, 0x00, 0x14
};

static int has_fply_prefix(const uint8_t *data, size_t len) {
    return data && len >= 7 &&
        data[0] == 0x46 && data[1] == 0x50 &&
        data[2] == 0x4C && data[3] == 0x59;
}

mlfp_context *mlfp_create(void) {
    return (mlfp_context *)calloc(1, sizeof(mlfp_context));
}

void mlfp_reset(mlfp_context *ctx) {
    if (!ctx) return;
    memset(ctx->key_message, 0, sizeof(ctx->key_message));
    ctx->key_message_len = 0;
#ifdef __APPLE__
    if (ctx->video_cryptor) {
        CCCryptorRelease(ctx->video_cryptor);
        ctx->video_cryptor = NULL;
    }
#endif
    ctx->video_ready = 0;
}

void mlfp_destroy(mlfp_context *ctx) {
    if (!ctx) return;
    mlfp_reset(ctx);
    free(ctx);
}

int mlfp_setup(
    mlfp_context *ctx,
    const uint8_t *request,
    size_t request_len,
    uint8_t *response,
    size_t response_capacity
) {
    if (!ctx || !request || !response) return -1;
    if (request_len != 16 || response_capacity < 142) return -2;
    if (!has_fply_prefix(request, request_len) || request[4] != 0x03 || request[6] != 0x01) return -3;

    const uint8_t mode = request[14];
    if (mode > 3) return -4;

    memcpy(response, k_phase2_responses[mode], 142);
    ctx->key_message_len = 0;
    return 142;
}

int mlfp_handshake(
    mlfp_context *ctx,
    const uint8_t *request,
    size_t request_len,
    uint8_t *response,
    size_t response_capacity
) {
    if (!ctx || !request || !response) return -1;
    if (request_len != 164 || response_capacity < 32) return -2;
    if (!has_fply_prefix(request, request_len) || request[4] != 0x03 || request[6] != 0x03) return -3;

    memcpy(ctx->key_message, request, 164);
    ctx->key_message_len = 164;

    memcpy(response, k_phase4_header, 12);
    memcpy(response + 12, request + 144, 20);
    return 32;
}

int mlfp_decrypt_session_key(
    mlfp_context *ctx,
    const uint8_t *encrypted_key,
    size_t encrypted_key_len,
    uint8_t *session_key,
    size_t session_key_capacity
) {
    if (!ctx || !encrypted_key || !session_key) return -1;
    if (ctx->key_message_len != 164) return -2;
    if (encrypted_key_len != 72 || session_key_capacity < 16) return -3;

    playfair_decrypt(ctx->key_message, (unsigned char *)encrypted_key, session_key);
    return 16;
}

int mlfp_prepare_video_crypto(
    mlfp_context *ctx,
    const uint8_t *session_key,
    size_t session_key_len,
    uint64_t stream_connection_id
) {
    if (!ctx || !session_key || session_key_len != 16) return -1;

#ifdef __APPLE__
    uint8_t key_digest[CC_SHA512_DIGEST_LENGTH] = {0};
    uint8_t iv_digest[CC_SHA512_DIGEST_LENGTH] = {0};
    char key_label[96] = {0};
    char iv_label[96] = {0};

    snprintf(key_label, sizeof(key_label), "AirPlayStreamKey%llu", (unsigned long long)stream_connection_id);
    snprintf(iv_label, sizeof(iv_label), "AirPlayStreamIV%llu", (unsigned long long)stream_connection_id);

    CC_SHA512_CTX sha;
    CC_SHA512_Init(&sha);
    CC_SHA512_Update(&sha, key_label, (CC_LONG)strlen(key_label));
    CC_SHA512_Update(&sha, session_key, 16);
    CC_SHA512_Final(key_digest, &sha);

    CC_SHA512_Init(&sha);
    CC_SHA512_Update(&sha, iv_label, (CC_LONG)strlen(iv_label));
    CC_SHA512_Update(&sha, session_key, 16);
    CC_SHA512_Final(iv_digest, &sha);

    if (ctx->video_cryptor) {
        CCCryptorRelease(ctx->video_cryptor);
        ctx->video_cryptor = NULL;
    }

    CCCryptorStatus status = CCCryptorCreateWithMode(
        kCCEncrypt,
        kCCModeCTR,
        kCCAlgorithmAES,
        ccNoPadding,
        iv_digest,
        key_digest,
        kCCKeySizeAES128,
        NULL,
        0,
        0,
        kCCModeOptionCTR_BE,
        &ctx->video_cryptor
    );

    if (status != kCCSuccess || !ctx->video_cryptor) {
        ctx->video_ready = 0;
        return -10 - (int)status;
    }

    ctx->video_ready = 1;
    return 0;
#else
    (void)stream_connection_id;
    ctx->video_ready = 0;
    return -20;
#endif
}

int mlfp_decrypt_video(
    mlfp_context *ctx,
    const uint8_t *input,
    size_t input_len,
    uint8_t *output,
    size_t output_capacity
) {
    if (!ctx || !input || !output) return -1;
    if (output_capacity < input_len) return -2;
    if (!ctx->video_ready) return -3;

#ifdef __APPLE__
    size_t moved = 0;
    CCCryptorStatus status = CCCryptorUpdate(
        ctx->video_cryptor,
        input,
        input_len,
        output,
        output_capacity,
        &moved
    );
    if (status != kCCSuccess) return -10 - (int)status;
    if (moved != input_len) return -30;
    return (int)moved;
#else
    return -20;
#endif
}

int mlfp_video_crypto_ready(const mlfp_context *ctx) {
    return ctx ? ctx->video_ready : 0;
}

int mlfp_decrypt_audio_cbc(
    mlfp_context *ctx,
    const uint8_t *session_key,
    size_t session_key_len,
    const uint8_t *iv,
    size_t iv_len,
    const uint8_t *input,
    size_t input_len,
    uint8_t *output,
    size_t output_capacity
) {
    (void)ctx;
    if (!session_key || !iv || !input || !output) return -1;
    if (session_key_len != 16 || iv_len != 16) return -2;
    if (output_capacity < input_len) return -3;

#ifdef __APPLE__
    const size_t encrypted_len = input_len & ~(size_t)0x0F;
    size_t moved = 0;

    if (encrypted_len > 0) {
        CCCryptorStatus status = CCCrypt(
            kCCDecrypt,
            kCCAlgorithmAES,
            0,
            session_key,
            kCCKeySizeAES128,
            iv,
            input,
            encrypted_len,
            output,
            output_capacity,
            &moved
        );
        if (status != kCCSuccess) return -10 - (int)status;
        if (moved != encrypted_len) return -30;
    }

    // RAOP/AirPlay realtime audio encrypts only complete AES blocks. Any
    // trailing bytes in the RTP payload are transmitted verbatim.
    if (encrypted_len < input_len) {
        memcpy(
            output + encrypted_len,
            input + encrypted_len,
            input_len - encrypted_len
        );
    }
    return (int)input_len;
#else
    return -20;
#endif
}

const char *mlfp_version(void) {
    return "MirrorLab PlayFair Provider 1.1";
}
